class Fibonacci {
	constructor(mod) {
		this.calculatedNumbers = new Map();
		this.calculatedNumbers.set(0n, 1n);
		this.calculatedNumbers.set(1n, 1n);
		this.mod = mod;
	}

	fib(n) {
		if (this.calculatedNumbers.has(n)) return this.calculatedNumbers.get(n);

		const k = n / 2n;
		let res;
		if (n % 2n === 0n) {
			res = (this.fib(k) * this.fib(k) + this.fib(k - 1n) * this.fib(k - 1n)) % this.mod;
		} else {
			res = (this.fib(k) * this.fib(k + 1n) + this.fib(k - 1n) * this.fib(k)) % this.mod;
		}
		this.calculatedNumbers.set(n, res);
		return res;
	}
}

class Exponentation {
	// a^b mod m
	static calc(a, b, m) {
		if (b === 0n) return 1n;
		if (b === 1n) return a;
		if (b % 2n === 0n) return Exponentation.calc(a * a % m, b / 2n, m);
		else return a * Exponentation.calc((a * a % m), (b - 1n) / 2n, m) % m;
	}
}

