		this.n = input.nextLong();
		this.k = input.nextLong();
		this.l = input.nextLong();
		this.MOD = input.nextLong();
	}

	solve(input, out) {
		this.read(input);
		if (this.l !== 64n && (1n << this.l) - 1n < this.k) {
			out.println(0);
			return;
		}

		const zeroPos = new Fibonacci(this.MOD).fib(this.n + 1n);
		let onePos = Exponentation.calc(2n, this.n, this.MOD) - zeroPos;
