		let res = 1n;
		for (let i = 0n; i < this.l; i++) {
			if ((this.k & (1n << i)) !== 0n) res *= onePos;
			else res *= zeroPos;
			res %= this.MOD;
		}
		out.println((res % this.MOD).toString());
	}
}

